INSERT INTO organization_relationships (id,source_org_id,target_org_id,relationship_type,description,source_type,source_name,verification_status,legacy_source,created_at,updated_at)
SELECT uuid_generate_v4(),a.id,b.id,'partnered_with'::relationship_type,'Patent co-applicant on '||s.n||' patent famil'||CASE WHEN s.n=1 THEN 'y' ELSE 'ies' END||'.','open_data','MESR Déposants des brevets (data.gouv.fr)','high','techbio_patents_november_2026',NOW(),NOW()
FROM src s JOIN organizations a ON a.slug=s.org JOIN organizations b ON b.slug=s.tgt
WHERE NOT EXISTS (SELECT 1 FROM organization_relationships x WHERE x.source_org_id=a.id AND x.target_org_id=b.id AND x.legacy_source='techbio_patents_november_2026');
